// E2E-048: A remote started through a symlinked working directory registers under the canonical real path, never the link
func TestE2E048(t *testing.T) {
	s := scenarios.New(t, "E2E-048")
	s.Given(`the "bare-host" project tree`)
	s.And(`the relay is running`)
	s.And(`a remote is running through a symlink to its project tree`)
	s.When(`the Product Owner opens "/"`)
	s.Then(`the session is listed`)
	s.And(`the session's folder is the project tree's real path`)
	s.And(`the session's row shows the project tree's real path`)
	s.But(`the session's row does not show the symlink path`)
	s.Done()
}

