// E2E-075: A browser mutation is admitted only with both the exact allowed origin and the expected host
func TestE2E075(t *testing.T) {
	s := scenarios.New(t, "E2E-075")
	s.Given(`the "bare-host" project tree`)
	s.And(`the relay is running`)
	s.And(`a remote is running`)
	s.When(`the Product Owner opens "/"`)
	s.Then(`a POST to "/api/sessions/{S}/runs" with the dispatch body and headers "origin: http://evil.example" returns status 403`)
	s.And(`a POST to "/api/sessions/{S}/runs" with the dispatch body and headers "origin: null" returns status 403`)
	s.And(`a POST to "/api/sessions/{S}/runs" with the dispatch body returns status 403`)
	s.And(`a POST to "/api/sessions/{S}/runs" with the dispatch body and headers "host: harness.example.com; origin: {BASE}" returns status 403`)
	s.And(`a POST to "/api/sessions/{S}/runs" with the dispatch body and headers "origin: {BASE}" does not return status 403`)
	s.Done()
}

// E2E-076: Every agent route refuses a present foreign origin and accepts an absent one on a loopback host, because the Go client sends no origin at all
func TestE2E076(t *testing.T) {
	s := scenarios.New(t, "E2E-076")
	s.Given(`the "bare-host" project tree`)
	s.And(`the relay is running`)
	s.And(`a remote is running`)
	s.When(`the Product Owner opens "/"`)
	s.Then(`a POST to "/api/agent/register" with the register body and headers "origin: http://evil.example" returns status 403`)
	s.And(`a POST to "/api/agent/register" with the register body and headers "host: harness.example.com" returns status 403`)
	s.And(`a POST to "/api/agent/register" with the register body returns status 200`)
	s.And(`a POST to "/api/agent/poll" with the poll body and headers "origin: http://evil.example" returns status 403`)
	s.And(`a POST to "/api/agent/poll" with the poll body and headers "host: harness.example.com" returns status 403`)
	s.And(`a POST to "/api/agent/poll" with the poll body returns status 204 or 200`)
	s.And(`a POST to "/api/agent/reply" with the reply body and headers "origin: http://evil.example" returns status 403`)
	s.And(`a POST to "/api/agent/reply" with the reply body does not return status 403`)
	s.And(`a GET to "/api/sessions" with headers "host: harness.example.com" returns status 403`)
	s.And(`a GET to "/api/sessions" returns status 200`)
	s.Done()
}

