	s.And(`the response names error "session_gone"`)
	s.And(`a GET to "/api/sessions/{MISSING}/runs/{MISSING}" with headers "host: true-bdd-app.vercel.app" returns status 404`)
	s.And(`a POST to "/api/agent/register" with the register body and headers "host: true-bdd-app.vercel.app" returns status 200`)
