// E2E-108: Another owner's run is readable through any live session on the project but answerable only through the one that owns it
func TestE2E108(t *testing.T) {
	s := scenarios.New(t, "E2E-108")
	s.Given(`the "bare-host" project tree`)
	s.And(`the relay is running`)
	s.And(`a remote is running as "A"`)
	s.And(`a remote is running as "B" in the same project tree`)
	s.And(`the Product Owner dispatches "prompt-probe" on session "B" as run "R1"`)
	s.And(`run "R1" publishes a "choice" prompt`)
	s.When(`the Product Owner answers the pending prompt of run "R1" through session "A" with "1"`)
	s.Then(`run "R1" is not answerable through session "A"`)
	s.And(`run "R1" is answerable through session "B"`)
	s.And(`the answer returned status 409`)
	s.And(`run "R1" still waits on the same prompt`)
	s.And(`answering the pending prompt of run "R1" through session "B" with "1" advances it past the prompt`)
	s.Done()
}

// E2E-109: A session registered on one relay instance is visible on the other, in both directions, because the registry is shared rather than held in a process
func TestE2E109(t *testing.T) {
	s := scenarios.New(t, "E2E-109")
	s.Given(`the "bare-host" project tree`)
	s.And(`relays "A" and "B" share one Redis`)
	s.When(`an agent "S1" is registered on relay "B"`)
	s.And(`an agent "S2" is registered on relay "A"`)
	s.Then(`session "S1" is listed on relay "A"`)
	s.And(`session "S2" is listed on relay "B"`)
	s.Done()
}

// E2E-110: A dispatch enqueued on one instance is claimed and answered on the other, delivered exactly once and never re-served from a retained body
func TestE2E110(t *testing.T) {
	s := scenarios.New(t, "E2E-110")
	s.Given(`the "bare-host" project tree`)
	s.And(`relays "A" and "B" share one Redis`)
	s.And(`an agent "S1" is registered on relay "B"`)
	s.And(`the Product Owner dispatches "version" on session "S1" through relay "A" as request "Q1"`)
	s.When(`agent "S1" polls relay "B" as work "W1"`)
	s.And(`agent "S1" replies to work "W1"`)
	s.Then(`work "W1" has type "dispatch"`)
	s.And(`work "W1" carries the dispatch payload of request "Q1"`)
	s.And(`request "Q1" completes with status 201`)
	s.And(`the Redis key "reply:W1" is gone`)
	s.And(`work "W1" is not redelivered`)
	s.Done()
}

// E2E-111: A read issued on one instance is served by the CLI polling the other
