// E2E-112: The queue a session may hold is counted across both instances, so capacity cannot be doubled by asking the other one
func TestE2E112(t *testing.T) {
	s := scenarios.New(t, "E2E-112")
	s.Given(`the "bare-host" project tree`)
	s.And(`relays "A" and "B" share one Redis with "HARNESS_MAX_PER_SESSION_QUEUE" set to "2"`)
	s.And(`an agent "S1" is registered on relay "B"`)
	s.When(`two claimed reads fill the queue for session "S1"`)
	s.Then(`a further status read of "S1" on relay "A" returns status 503`)
	s.And(`a further status read of "S1" on relay "B" returns status 503`)
	s.Done()
}

// E2E-113: A reply carrying the wrong token for a session registered on the other instance is refused as a bad token, proving the shared registry authenticated it
