// E2E-116: A claimed dispatch that outran the browser's deadline accepts one late reply and refuses the second, because the relay forwards rather than stores
func TestE2E116(t *testing.T) {
	s := scenarios.New(t, "E2E-116")
	s.Given(`the "bare-host" project tree`)
	s.And(`relays "A" and "B" share one Redis`)
	s.And(`an agent "S1" is registered on relay "A"`)
	s.And(`the Product Owner dispatches "version" on session "S1" through relay "A" as request "Q1"`)
	s.When(`agent "S1" polls relay "B" as work "W1"`)
	s.Then(`request "Q1" completes with status 504`)
	s.And(`replying to work "W1" on relay "B" returns status 200`)
	s.And(`replying to work "W1" on relay "B" again returns status 409`)
	s.And(`the Redis key "reply:W1" does not hold the late reply`)
	s.Done()
}

// E2E-117: A run the CLI committed while the browser gave up is recovered by re-dispatching its token, and the project still holds exactly one run
func TestE2E117(t *testing.T) {
	s := scenarios.New(t, "E2E-117")
	s.Given(`the "bare-host" project tree`)
	s.And(`relays "A" and "B" share one Redis`)
	s.And(`a remote is running against relay "B"`)
	s.And(`the Product Owner dispatches "version" on the session through relay "A" as run "R1"`)
	s.And(`run "R1" reaches a terminal state`)
	s.When(`the Product Owner dispatches "version" on the session reusing the token of run "R1"`)
	s.Then(`dispatching the same token returns run "R1" with status 200`)
	s.And(`the project has exactly 1 run`)
	s.And(`the project's only run is run "R1"`)
	s.Done()
}

// E2E-118: Sweeping a session that stopped answering reclaims the capacity its abandoned work held, so dead sessions cannot exhaust the relay over time
func TestE2E118(t *testing.T) {
	s := scenarios.New(t, "E2E-118")
	s.Given(`the "bare-host" project tree`)
	s.And(`the relay is running with "HARNESS_MAX_GLOBAL_QUEUE" set to "1"`)
	s.And(`an agent "S1" is registered and never polls`)
	s.And(`the Product Owner reads the session detail of "S1" as request "Q1"`)
	s.When(`session "S1" is swept out of the registry`)
	s.Then(`a further session detail read of "S1" returned status 503 before the sweep`)
	s.And(`request "Q1" completes with status 404`)
	s.And(`a read for a freshly registered session is enqueued and served`)
	s.Done()
}

// E2E-119: A late reply arriving after the orphan window is refused as unknown work, because the record it would correlate to was reclaimed
func TestE2E119(t *testing.T) {
	s := scenarios.New(t, "E2E-119")
	s.Given(`the "bare-host" project tree`)
	s.And(`the relay is running with "HARNESS_ORPHAN_TTL_SEC" set to "5"`)
	s.And(`an agent "S1" is registered and never polls`)
	s.And(`the Product Owner dispatches "version" on session "S1" as request "Q1"`)
	s.When(`agent "S1" polls as work "W1"`)
	s.Then(`request "Q1" completes with status 504`)
	s.And(`work "W1" is in state "orphaned"`)
	s.And(`work "W1" has a positive TTL of at most 5 seconds`)
	s.And(`the Redis key "work:W1" is gone`)
	s.And(`replying to work "W1" returns status 409`)
	s.And(`the response names error "unknown_work"`)
	s.And(`the Redis key "reply:W1" is gone`)
	s.Done()
}
